# Chart Builder — Recharts for Shopify Analytics

## AUTO-DETECT TRIGGERS
- User mentions: chart, graph, visualization, funnel, bar chart, line chart, donut
- Analytics dashboard needs visual data representation
- Quiz completion rate, drop-off analysis, or conversion charts
- Trend over time visualization (responses per day/week)

## DECISION TREE
```
Need a chart? →
  Completion funnel (started → completed → converted)? → FunnelChart
  Drop-off per question? → BarChart (horizontal)
  Responses over time? → LineChart with daily/weekly grouping
  Device breakdown? → PieChart / DonutChart
  Loading? → Skeleton placeholder (never spinner)
  No data? → Empty state with call to action
```

## SETUP & TYPES

```typescript
// Install: npm install recharts
// app/components/charts/types.ts
export interface FunnelData {
  name: string;
  value: number;
  fill: string;
}

export interface TimeSeriesPoint {
  date: string;          // "2024-01-15"
  completions: number;
  started: number;
}

export interface DropOffPoint {
  question: string;
  answered: number;
  dropped: number;
  dropRate: number;
}

export interface DeviceBreakdown {
  name: string;
  value: number;
  color: string;
}
```

## FUNNEL CHART (Quiz Completion Funnel)

```typescript
// app/components/charts/CompletionFunnel.tsx
import {
  BarChart, Bar, XAxis, YAxis, CartesianGrid,
  Tooltip, ResponsiveContainer, Cell, LabelList
} from "recharts";
import { Card, Text, Box, SkeletonBodyText } from "@shopify/polaris";

interface Props {
  started: number;
  completed: number;
  converted: number;
  loading?: boolean;
}

const FUNNEL_COLORS = ["#5C6AC4", "#00A651", "#F49342"];

export function CompletionFunnel({ started, completed, converted, loading }: Props) {
  if (loading) {
    return (
      <Card>
        <Box padding="400">
          <SkeletonBodyText lines={6} />
        </Box>
      </Card>
    );
  }

  if (started === 0) {
    return (
      <Card>
        <Box padding="600">
          <Text alignment="center" tone="subdued">
            No quiz responses yet. Share your quiz to start collecting data.
          </Text>
        </Box>
      </Card>
    );
  }

  const data: FunnelData[] = [
    { name: "Started", value: started, fill: FUNNEL_COLORS[0] },
    { name: "Completed", value: completed, fill: FUNNEL_COLORS[1] },
    { name: "Converted", value: converted, fill: FUNNEL_COLORS[2] },
  ];

  return (
    <Card>
      <Box padding="400">
        <Text variant="headingMd" as="h3">Completion Funnel</Text>
        <Box paddingBlockStart="400">
          <ResponsiveContainer width="100%" height={220}>
            <BarChart data={data} layout="vertical" margin={{ left: 20, right: 40 }}>
              <CartesianGrid strokeDasharray="3 3" horizontal={false} />
              <XAxis type="number" hide />
              <YAxis type="category" dataKey="name" width={80} />
              <Tooltip
                formatter={(value: number) => [value.toLocaleString(), "Count"]}
              />
              <Bar dataKey="value" radius={[0, 4, 4, 0]}>
                {data.map((entry, index) => (
                  <Cell key={index} fill={entry.fill} />
                ))}
                <LabelList
                  dataKey="value"
                  position="right"
                  formatter={(v: number) => v.toLocaleString()}
                  style={{ fontWeight: "bold", fontSize: 13 }}
                />
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </Box>
        <InlineStack gap="400" align="center">
          <Text tone="subdued" variant="bodySm">
            Completion rate: {started > 0 ? Math.round((completed / started) * 100) : 0}%
          </Text>
          <Text tone="subdued" variant="bodySm">
            Conversion rate: {completed > 0 ? Math.round((converted / completed) * 100) : 0}%
          </Text>
        </InlineStack>
      </Box>
    </Card>
  );
}
```

## LINE CHART (Completions Over Time)

```typescript
// app/components/charts/CompletionsOverTime.tsx
import {
  LineChart, Line, XAxis, YAxis, CartesianGrid,
  Tooltip, ResponsiveContainer, Legend
} from "recharts";

interface Props {
  data: TimeSeriesPoint[];
  loading?: boolean;
}

export function CompletionsOverTime({ data, loading }: Props) {
  if (loading) return <SkeletonBodyText lines={8} />;

  return (
    <ResponsiveContainer width="100%" height={280}>
      <LineChart data={data} margin={{ top: 5, right: 20, bottom: 5, left: 0 }}>
        <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
        <XAxis
          dataKey="date"
          tickFormatter={(d) => new Date(d).toLocaleDateString("en-US", { month: "short", day: "numeric" })}
          tick={{ fontSize: 12 }}
        />
        <YAxis tick={{ fontSize: 12 }} />
        <Tooltip
          labelFormatter={(d) => new Date(d).toLocaleDateString("en-US", { weekday: "long", month: "long", day: "numeric" })}
          formatter={(value: number, name: string) => [value.toLocaleString(), name === "completions" ? "Completed" : "Started"]}
        />
        <Legend />
        <Line type="monotone" dataKey="started" stroke="#5C6AC4" strokeWidth={2} dot={false} name="Started" />
        <Line type="monotone" dataKey="completions" stroke="#00A651" strokeWidth={2} dot={false} name="Completed" />
      </LineChart>
    </ResponsiveContainer>
  );
}
```

## BAR CHART (Question Drop-Off)

```typescript
// app/components/charts/QuestionDropOff.tsx
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from "recharts";

export function QuestionDropOff({ data }: { data: DropOffPoint[] }) {
  return (
    <ResponsiveContainer width="100%" height={250}>
      <BarChart data={data} margin={{ top: 5, right: 20, bottom: 40, left: 0 }}>
        <CartesianGrid strokeDasharray="3 3" />
        <XAxis
          dataKey="question"
          angle={-30}
          textAnchor="end"
          tick={{ fontSize: 11 }}
          interval={0}
        />
        <YAxis tickFormatter={(v) => `${v}%`} domain={[0, 100]} />
        <Tooltip
          formatter={(v: number) => [`${v.toFixed(1)}%`, "Drop Rate"]}
        />
        <Bar dataKey="dropRate" fill="#D72C0D" name="Drop Rate (%)" radius={[4, 4, 0, 0]} />
      </BarChart>
    </ResponsiveContainer>
  );
}
```

## DONUT CHART (Device Breakdown)

```typescript
// app/components/charts/DeviceChart.tsx
import { PieChart, Pie, Cell, Tooltip, Legend, ResponsiveContainer } from "recharts";

const DEVICE_COLORS: Record<string, string> = {
  mobile: "#5C6AC4",
  desktop: "#00A651",
  tablet: "#F49342",
  unknown: "#9AA0A6",
};

export function DeviceChart({ data }: { data: DeviceBreakdown[] }) {
  const total = data.reduce((s, d) => s + d.value, 0);

  return (
    <ResponsiveContainer width="100%" height={220}>
      <PieChart>
        <Pie
          data={data}
          cx="50%"
          cy="50%"
          innerRadius={55}
          outerRadius={80}
          paddingAngle={3}
          dataKey="value"
          label={({ name, percent }) => `${name} ${Math.round(percent * 100)}%`}
          labelLine={false}
        >
          {data.map((entry, i) => (
            <Cell key={i} fill={DEVICE_COLORS[entry.name.toLowerCase()] ?? "#9AA0A6"} />
          ))}
        </Pie>
        <Tooltip formatter={(v: number) => [`${v.toLocaleString()} (${Math.round((v / total) * 100)}%)`, "Sessions"]} />
        <Legend />
      </PieChart>
    </ResponsiveContainer>
  );
}
```

## DATA PREPARATION HELPERS

```typescript
// app/utils/chart-data.ts
export function groupResponsesByDay(
  responses: Array<{ createdAt: Date; completedAt: Date | null }>
): TimeSeriesPoint[] {
  const byDay = new Map<string, { started: number; completions: number }>();
  for (const r of responses) {
    const day = r.createdAt.toISOString().split("T")[0];
    const current = byDay.get(day) ?? { started: 0, completions: 0 };
    current.started++;
    if (r.completedAt) current.completions++;
    byDay.set(day, current);
  }
  return Array.from(byDay.entries())
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([date, vals]) => ({ date, ...vals }));
}
```

## SPAWN AGENTS
- `analytics-builder` — chart data aggregation queries
- `real-time-builder` — auto-refreshing charts with polling
- `report-generator` — export chart data as CSV

## SELF-VALIDATION CHECKLIST
- [ ] `recharts` installed (not Chart.js — avoid extra bundle size)
- [ ] `ResponsiveContainer` wraps every chart for mobile responsiveness
- [ ] Loading skeleton shown (not spinner) while data fetches
- [ ] Empty state shown with actionable CTA when no data
- [ ] Shopify Polaris color palette used (#5C6AC4, #00A651, etc.)
- [ ] Tooltips format numbers with `toLocaleString()`
- [ ] Charts accessible (aria labels, not just color coding)
- [ ] Chart containers have fixed height (not 100% height on both axes)
- [ ] Date labels formatted in human-readable form
- [ ] Percentage calculations guard against division by zero

## NEVER
- Never use Chart.js (larger bundle, less React-friendly than recharts)
- Never render charts without a loading state
- Never show raw numbers in tooltips without formatting (use toLocaleString)
- Never use colors that don't meet WCAG AA contrast ratio
- Never forget empty state when dataset is empty

