```

### FORMS & INPUT

```tsx
import { FormLayout, TextField, Select, Checkbox, ChoiceList, RangeSlider, ColorPicker } from "@shopify/polaris";

// Standard form
<FormLayout>
  <TextField
    label="Quiz title"
