// Metric card pattern (no official Polaris component — use Card + Text)
interface MetricCardProps {
  title: string;
  value: string | number;
  change?: number;     // percentage change vs. previous period
  loading?: boolean;
}

function MetricCard({ title, value, change, loading }: MetricCardProps) {
  if (loading) {
    return (
      <Card>
        <BlockStack gap="200">
          <SkeletonBodyText lines={1} />
          <SkeletonDisplayText size="large" />
        </BlockStack>
      </Card>
    );
  }

  const changeTone = change === undefined ? undefined : change >= 0 ? "success" : "critical";
  const changePrefix = change === undefined ? "" : change >= 0 ? "+" : "";

  return (
    <Card>
      <BlockStack gap="200">
        <Text variant="bodySm" tone="subdued" as="p">{title}</Text>
        <Text variant="heading2xl" as="p" fontWeight="bold">
          {typeof value === "number" ? value.toLocaleString() : value}
        </Text>
        {change !== undefined && (
          <Text variant="bodySm" tone={changeTone}>
            {changePrefix}{change.toFixed(1)}% vs. last period
          </Text>
        )}
      </BlockStack>
    </Card>
  );
}
