import { Badge } from "@shopify/polaris";

// Quiz status badges
function QuizStatusBadge({ status }: { status: string }) {
  const config: Record<string, { tone: "success" | "warning" | "info" | "attention" | undefined; label: string }> = {
    active:   { tone: "success", label: "Active" },
    draft:    { tone: undefined, label: "Draft" },   // No tone = neutral grey
    paused:   { tone: "warning", label: "Paused" },
    archived: { tone: "attention", label: "Archived" },
  };
  const { tone, label } = config[status] ?? { tone: undefined, label: status };
  return <Badge tone={tone}>{label}</Badge>;
}

// Plan badge
function PlanBadge({ plan }: { plan: string }) {
  if (plan === "enterprise") return <Badge tone="success">Enterprise</Badge>;
  if (plan === "pro") return <Badge tone="info">Pro</Badge>;
  if (plan === "starter") return <Badge>Starter</Badge>;
  return <Badge tone="attention">Free</Badge>;
}
