import { IndexFilters, useSetIndexFiltersMode, FilterInterface } from "@shopify/polaris";

function QuizFilters({ onFilter }: { onFilter: (params: FilterParams) => void }) {
  const { mode, setMode } = useSetIndexFiltersMode();
  const [queryValue, setQueryValue] = useState("");
  const [statusFilter, setStatusFilter] = useState<string[]>([]);

  const filters: FilterInterface[] = [
    {
      key: "status",
      label: "Status",
      filter: (
        <ChoiceList
          title="Status"
          titleHidden
          choices={[
            { label: "Active", value: "active" },
            { label: "Draft", value: "draft" },
            { label: "Paused", value: "paused" },
          ]}
          selected={statusFilter}
          onChange={setStatusFilter}
          allowMultiple
        />
      ),
      shortcut: true,
    },
  ];

  const appliedFilters = statusFilter.length > 0
    ? [{ key: "status", label: `Status: ${statusFilter.join(", ")}`, onRemove: () => setStatusFilter([]) }]
    : [];

  return (
    <IndexFilters
      queryValue={queryValue}
      queryPlaceholder="Search quizzes..."
      onQueryChange={setQueryValue}
      onQueryClear={() => setQueryValue("")}
      filters={filters}
      appliedFilters={appliedFilters}
      onClearAll={() => { setQueryValue(""); setStatusFilter([]); }}
      mode={mode}
      setMode={setMode}
      tabs={[]}
      selected={0}
      onSelect={() => {}}
      canCreateNewView={false}
    />
  );
}
