```tsx
// Sortable question list using native HTML5 drag + Polaris UI
function QuestionsTab({ questions, quizId, onQuestionChange }: QuestionsTabProps) {
  const submit = useSubmit();
  const [expandedId, setExpandedId] = useState<string | null>(null);

  const handleReorder = (newOrder: string[]) => {
    submit(
      { intent: "reorder", questionIds: JSON.stringify(newOrder) },
      { method: "post", action: `/app/quizzes/${quizId}/questions` }
    );
    onQuestionChange();
  };

  const handleAddQuestion = (type: string) => {
    submit(
      { intent: "add", type },
      { method: "post", action: `/app/quizzes/${quizId}/questions` }
    );
  };

  return (
    <BlockStack gap="400">
      {questions.length === 0 ? (
        <EmptyState
          heading="Add your first question"
          image="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png"
          action={{ content: "Add question", onAction: () => handleAddQuestion("multiple_choice") }}
        >
          <p>Questions guide shoppers to the perfect product recommendation.</p>
        </EmptyState>
      ) : (
        <BlockStack gap="300">
          {questions.map((q, index) => (
            <QuestionCard
              key={q.id}
              question={q}
              index={index}
              isExpanded={expandedId === q.id}
              onToggle={() => setExpandedId(expandedId === q.id ? null : q.id)}
              onDelete={() => handleDeleteQuestion(q.id)}
              onChange={onQuestionChange}
            />
          ))}
        </BlockStack>
      )}

      {/* Add question button with type picker */}
      <InlineStack gap="200">
        <Button onClick={() => handleAddQuestion("multiple_choice")} icon={PlusIcon}>
          Add multiple choice
        </Button>
        <Button variant="plain" onClick={() => handleAddQuestion("image_choice")} icon={ImageIcon}>
          Image choice
        </Button>
        <Button variant="plain" onClick={() => handleAddQuestion("slider")} icon={SliderIcon}>
          Slider
        </Button>
        <Button variant="plain" onClick={() => handleAddQuestion("text_input")} icon={TextIcon}>
          Text input
        </Button>
