import { Page, Layout, Card, IndexTable, IndexFilters, useSetIndexFiltersMode, EmptyState, Badge, Button, Text, InlineStack, BlockStack, Link } from "@shopify/polaris";

export default function QuizzesPage() {
  const { quizzes, pagination } = useLoaderData<typeof loader>();
  const submit = useSubmit();
