  const [queryValue, setQueryValue] = useState("");
  const [statusFilter, setStatusFilter] = useState<string[]>([]);
  const isLoading = navigation.state === "loading";

  const filteredQuizzes = quizzes.filter(q => {
    const matchesQuery = q.title.toLowerCase().includes(queryValue.toLowerCase());
    const matchesStatus = statusFilter.length === 0 || statusFilter.includes(q.status);
    return matchesQuery && matchesStatus;
  });

  return (
    <Page
      title="Quizzes"
      primaryAction={{
        content: "Create quiz",
        url: "/app/quizzes/new",
      }}
      secondaryActions={[
        { content: "Templates", url: "/app/templates" },
      ]}
    >
      <Layout>
        <Layout.Section>
          <Card padding="0">
            <IndexFilters
              queryValue={queryValue}
              queryPlaceholder="Search quizzes..."
              onQueryChange={setQueryValue}
              onQueryClear={() => setQueryValue("")}
              filters={[
                {
                  key: "status",
                  label: "Status",
                  filter: (
                    <ChoiceList
                      title="Status"
                      titleHidden
                      choices={[
