                  ),
                  shortcut: true,
                },
              ]}
              appliedFilters={statusFilter.length > 0 ? [{
                key: "status",
                label: `Status: ${statusFilter.join(", ")}`,
                onRemove: () => setStatusFilter([]),
              }] : []}
              onClearAll={() => { setQueryValue(""); setStatusFilter([]); }}
              mode={mode}
              setMode={setMode}
              tabs={[]}
              selected={0}
              onSelect={() => {}}
