## QUIZ EDITOR (MASTER PATTERN)

The quiz editor is the most complex page. It uses a 5-tab layout with a persistent header.

```tsx
// app/routes/app.quizzes.$id.tsx
import { Page, Tabs, Card, BlockStack, InlineStack, Badge, Button, Banner, Text } from "@shopify/polaris";
import { useLoaderData, useActionData, useNavigation, useSubmit, useBlocker } from "react-router";
import { useState, useEffect, useCallback } from "react";

const TABS = [
  { id: "questions", content: "Questions", panelID: "questions-panel" },
  { id: "results", content: "Results", panelID: "results-panel" },
  { id: "design", content: "Design", panelID: "design-panel" },
  { id: "settings", content: "Settings", panelID: "settings-panel" },
  { id: "preview", content: "Preview", panelID: "preview-panel" },
] as const;

type TabId = typeof TABS[number]["id"];

export default function QuizEditorPage() {
  const { quiz, questions, resultPages } = useLoaderData<typeof loader>();
  const actionData = useActionData<typeof action>();
  const navigation = useNavigation();
  const submit = useSubmit();

  const [selectedTab, setSelectedTab] = useState(0);
  const [isDirty, setIsDirty] = useState(false);
  const [formState, setFormState] = useState({ title: quiz.title, description: quiz.description ?? "" });

  const isSaving = navigation.state === "submitting" && navigation.formData?.get("intent") === "save";
  const isPublishing = navigation.state === "submitting" && navigation.formData?.get("intent") === "publish";

  // Unsaved changes blocker
  const blocker = useBlocker(({ currentLocation, nextLocation }) =>
    isDirty && currentLocation.pathname !== nextLocation.pathname
  );

  // Toast on save success
  useEffect(() => {
    if (actionData?.toast) shopify.toast.show(actionData.toast);
    if (actionData?.error) shopify.toast.show(actionData.error, { isError: true });
  }, [actionData]);

  const handleSave = useCallback(() => {
    submit({ intent: "save", ...formState }, { method: "post" });
    setIsDirty(false);
  }, [formState, submit]);

  const handlePublish = useCallback(() => {
    submit({ intent: "publish" }, { method: "post" });
  }, [submit]);

  const statusTone = { active: "success", draft: undefined, paused: "warning", archived: "attention" }[quiz.status] as "success" | "warning" | "attention" | undefined;

  return (
    <Page
      title={quiz.title}
      backAction={{ content: "Quizzes", url: "/app/quizzes" }}
      primaryAction={
        quiz.status === "draft"
          ? { content: "Publish quiz", onAction: handlePublish, loading: isPublishing }
          : { content: "Save", onAction: handleSave, loading: isSaving }
      }
      secondaryActions={[
        { content: "Save draft", onAction: handleSave, loading: isSaving, disabled: !isDirty },
        { content: "Preview", url: `/app/quizzes/${quiz.id}/preview`, target: "_blank" },
        {
          content: quiz.status === "active" ? "Pause quiz" : "Duplicate",
          onAction: quiz.status === "active" ? handlePause : handleDuplicate,
        },
      ]}
      titleMetadata={<Badge tone={statusTone}>{quiz.status.charAt(0).toUpperCase() + quiz.status.slice(1)}</Badge>}
    >
      <BlockStack gap="400">
        {/* Unsaved changes warning */}
        {isDirty && (
          <Banner tone="warning" title="You have unsaved changes">
            <InlineStack gap="200">
              <Button size="slim" onClick={handleSave} loading={isSaving}>Save now</Button>
              <Button size="slim" variant="plain" onClick={() => { setFormState({ title: quiz.title, description: quiz.description ?? "" }); setIsDirty(false); }}>Discard</Button>
            </InlineStack>
          </Banner>
        )}

        {/* Unsaved navigation blocker */}
        {blocker.state === "blocked" && (
          <Banner tone="critical" title="Leave without saving?">
            <InlineStack gap="200">
              <Button size="slim" tone="critical" onClick={() => blocker.proceed()}>Leave</Button>
              <Button size="slim" variant="plain" onClick={() => blocker.reset()}>Stay</Button>
            </InlineStack>
          </Banner>
        )}

        <Tabs tabs={TABS} selected={selectedTab} onSelect={setSelectedTab} fitted>
          <Card>
            <BlockStack gap="400">
              {selectedTab === 0 && (
                <QuestionsTab
                  questions={questions}
                  quizId={quiz.id}
                  onQuestionChange={() => setIsDirty(true)}
                />
              )}
              {selectedTab === 1 && (
                <ResultsTab
                  resultPages={resultPages}
                  quizId={quiz.id}
                  quizType={quiz.type}
                />
              )}
              {selectedTab === 2 && (
                <DesignTab
                  quiz={quiz}
                  onChange={(styling) => { setFormState(f => ({ ...f, styling })); setIsDirty(true); }}
                />
              )}
              {selectedTab === 3 && (
                <SettingsTab
                  quiz={quiz}
                  formState={formState}
                  onChange={(updates) => { setFormState(f => ({ ...f, ...updates })); setIsDirty(true); }}
                />
              )}
              {selectedTab === 4 && (
                <PreviewTab quizId={quiz.id} quizSlug={quiz.slug} shop={quiz.shop} />
              )}
            </BlockStack>
          </Card>
        </Tabs>
      </BlockStack>
    </Page>
  );
}
```

