## DASHBOARD PAGE (app/routes/app._index.tsx)

```tsx
import { json, type LoaderFunctionArgs } from "@shopify/shopify-app-react-router";
import { useLoaderData } from "react-router";
import { authenticate } from "../shopify.server";
import db from "../db.server";
import {
  Page, Layout, Card, Text, BlockStack, InlineStack,
  Grid, Badge, Button, Banner, SkeletonBodyText, Divider
} from "@shopify/polaris";

export async function loader({ request }: LoaderFunctionArgs) {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;

  const [quizCount, activeQuizCount, totalCompletions, recentQuizzes] = await Promise.all([
    db.quiz.count({ where: { shop } }),
    db.quiz.count({ where: { shop, status: "active" } }),
    db.quiz.aggregate({ where: { shop }, _sum: { completions: true } }),
    db.quiz.findMany({
      where: { shop },
      orderBy: { updatedAt: "desc" },
      take: 5,
      select: { id: true, title: true, status: true, completions: true, updatedAt: true },
    }),
  ]);

  const subscription = await db.subscription.findUnique({ where: { shop } });

  return json({
    stats: {
      quizCount,
      activeQuizCount,
      totalCompletions: totalCompletions._sum.completions ?? 0,
    },
    recentQuizzes,
    plan: subscription?.plan ?? "free",
  });
