import { json, type LoaderFunctionArgs, type ActionFunctionArgs } from "@shopify/shopify-app-react-router";
import { useLoaderData, useActionData, useNavigation, useSubmit } from "react-router";
import { authenticate } from "../shopify.server";
import db from "../db.server";
import {
  Page, Layout, Card, FormLayout, TextField, Select,
  Button, Toast, Frame, BlockStack, Text, Divider, InlineStack
} from "@shopify/polaris";
import { useState, useEffect, useCallback } from "react";

export async function loader({ request }: LoaderFunctionArgs) {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;

  const [widgetConfig, subscription] = await Promise.all([
    db.widgetConfig.findUnique({ where: { shop } }),
    db.subscription.findUnique({ where: { shop } }),
  ]);

  return json({ widgetConfig, plan: subscription?.plan ?? "free", shop });
}

export async function action({ request }: ActionFunctionArgs) {
  const { session } = await authenticate.admin(request);
  const formData = await request.formData();
  const intent = formData.get("intent") as string;
  const shop = session.shop;

  try {
    switch (intent) {
      case "updateWidgetConfig": {
        await db.widgetConfig.upsert({
          where: { shop },
          update: {
            primaryColor: formData.get("primaryColor") as string || "#5C6AC4",
            fontFamily: formData.get("fontFamily") as string || "Inter",
            borderRadius: parseInt(formData.get("borderRadius") as string || "8"),
            triggerType: formData.get("triggerType") as string || "button",
            position: formData.get("position") as string || "bottom-right",
          },
          create: {
            shop,
            primaryColor: formData.get("primaryColor") as string || "#5C6AC4",
            fontFamily: formData.get("fontFamily") as string || "Inter",
            borderRadius: parseInt(formData.get("borderRadius") as string || "8"),
            triggerType: formData.get("triggerType") as string || "button",
            position: formData.get("position") as string || "bottom-right",
          },
        });
        return json({ success: true, message: "Settings saved" });
      }
      default:
        return json({ error: "Unknown action" }, { status: 400 });
    }
  } catch (error) {
    return json({ error: error instanceof Error ? error.message : "An error occurred" }, { status: 500 });
  }
}

export default function SettingsPage() {
  const { widgetConfig, plan } = useLoaderData<typeof loader>();
  const actionData = useActionData<typeof action>();
  const navigation = useNavigation();
  const submit = useSubmit();

  const [primaryColor, setPrimaryColor] = useState(widgetConfig?.primaryColor ?? "#5C6AC4");
  const [toastActive, setToastActive] = useState(false);
  const [toastMessage, setToastMessage] = useState("");
  const [toastError, setToastError] = useState(false);

  useEffect(() => {
    if (actionData?.success) { setToastMessage(actionData.message); setToastError(false); setToastActive(true); }
    if (actionData?.error) { setToastMessage(actionData.error); setToastError(true); setToastActive(true); }
  }, [actionData]);

  const handleSave = useCallback(() => {
    submit({ intent: "updateWidgetConfig", primaryColor }, { method: "POST" });
  }, [submit, primaryColor]);

  return (
    <Frame>
      <Page
        title="Settings"
        primaryAction={{ content: "Save", loading: navigation.state !== "idle", onAction: handleSave }}
      >
        <Layout>
          <Layout.Section>
            <Card>
              <BlockStack gap="400">
                <Text as="h2" variant="headingSm">Widget Appearance</Text>
                <Divider />
                <FormLayout>
                  <TextField
                    label="Primary Color"
                    value={primaryColor}
                    onChange={setPrimaryColor}
                    autoComplete="off"
                    helpText="Hex color for buttons and accents (e.g. #5C6AC4)"
                  />
                </FormLayout>
              </BlockStack>
            </Card>
          </Layout.Section>

          <Layout.Section variant="oneThird">
            <Card>
              <BlockStack gap="300">
                <Text as="h3" variant="headingSm">Current Plan</Text>
                <Text as="p" variant="bodyMd" fontWeight="bold">{plan.charAt(0).toUpperCase() + plan.slice(1)}</Text>
                <Button url="/app/settings/billing" variant="plain">Manage billing →</Button>
              </BlockStack>
            </Card>
          </Layout.Section>
        </Layout>
      </Page>
      {toastActive && <Toast content={toastMessage} error={toastError} onDismiss={() => setToastActive(false)} />}
    </Frame>
  );
}
