import { useLoaderData, useActionData, useNavigation, useSubmit } from "react-router";
import { useAppBridge } from "@shopify/app-bridge-react";
import { authenticate } from "../shopify.server";
import db from "../db.server";
import { Page, Layout, Card, EmptyState, SkeletonPage, SkeletonBodyText, BlockStack } from "@shopify/polaris";
// ✅ NO Toast, NO Frame imports — use shopify.toast.show() instead
import { useEffect } from "react";

export async function loader({ request }: LoaderFunctionArgs) {
  const { session } = await authenticate.admin(request);
  // CRITICAL: ALL queries MUST include shop: session.shop
  const data = await db.quiz.findMany({ where: { shop: session.shop } });
  return json({ data });
}

export async function action({ request }: ActionFunctionArgs) {
  const { session } = await authenticate.admin(request);
  const formData = await request.formData();
  const intent = formData.get("intent") as string;
  try {
    switch (intent) {
      case "doSomething": {
        // ... handle
        return json({ toast: "Done!" });
      }
      default:
        return json({ error: "Unknown action" }, { status: 400 });
    }
  } catch (error) {
    return json({ error: error instanceof Error ? error.message : "Error occurred" }, { status: 500 });
  }
}

export default function MyPage() {
  const { data } = useLoaderData<typeof loader>();
  const actionData = useActionData<typeof action>();
  const navigation = useNavigation();
  const shopify = useAppBridge(); // App Bridge v4 instance

  // ✅ Toast via App Bridge — no Polaris Toast/Frame needed
  useEffect(() => {
    if (actionData?.toast) shopify.toast.show(actionData.toast);
