## SETTINGS PAGE PATTERN (app/routes/app.settings.tsx)

```tsx
import { json, type LoaderFunctionArgs, type ActionFunctionArgs } from "@shopify/shopify-app-react-router";
import { useLoaderData, useActionData, useNavigation, useSubmit } from "react-router";
import { useAppBridge } from "@shopify/app-bridge-react";
import { authenticate } from "../shopify.server";
import db from "../db.server";
import {
  Page, Layout, Card, FormLayout, TextField, Select,
  Button, BlockStack, Text, Divider, InlineStack, Banner
} from "@shopify/polaris";
// NOTE: Do NOT import Toast or Frame from @shopify/polaris in embedded apps.
// Use shopify.toast.show() from App Bridge v4 instead.
import { useState, useEffect, useCallback } from "react";

export async function loader({ request }: LoaderFunctionArgs) {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;

  const [widgetConfig, subscription] = await Promise.all([
    db.widgetConfig.findUnique({ where: { shop } }),
    db.subscription.findUnique({ where: { shop } }),
  ]);

  return json({ widgetConfig, plan: subscription?.plan ?? "free", shop });
}

export async function action({ request }: ActionFunctionArgs) {
  const { session } = await authenticate.admin(request);
  const formData = await request.formData();
  const intent = formData.get("intent") as string;
  const shop = session.shop;

  try {
    switch (intent) {
      case "updateWidgetConfig": {
        await db.widgetConfig.upsert({
          where: { shop },
          update: {
            primaryColor: formData.get("primaryColor") as string || "#5C6AC4",
            fontFamily: formData.get("fontFamily") as string || "Inter",
            borderRadius: parseInt(formData.get("borderRadius") as string || "8"),
            triggerType: formData.get("triggerType") as string || "button",
            position: formData.get("position") as string || "bottom-right",
          },
          create: {
            shop,
            primaryColor: formData.get("primaryColor") as string || "#5C6AC4",
            fontFamily: formData.get("fontFamily") as string || "Inter",
            borderRadius: parseInt(formData.get("borderRadius") as string || "8"),
            triggerType: formData.get("triggerType") as string || "button",
            position: formData.get("position") as string || "bottom-right",
          },
        });
        return json({ success: true, message: "Settings saved" });
      }
      default:
        return json({ error: "Unknown action" }, { status: 400 });
    }
  } catch (error) {
    return json({ error: error instanceof Error ? error.message : "An error occurred" }, { status: 500 });
  }
}

export default function SettingsPage() {
  const { widgetConfig, plan } = useLoaderData<typeof loader>();
  const actionData = useActionData<typeof action>();
  const navigation = useNavigation();
  const submit = useSubmit();

  const shopify = useAppBridge();
  const [primaryColor, setPrimaryColor] = useState(widgetConfig?.primaryColor ?? "#5C6AC4");

  // Use App Bridge v4 toast — NOT Polaris Toast/Frame
  useEffect(() => {
    if (actionData?.success) shopify.toast.show(actionData.message ?? "Saved", { duration: 3000 });
    if (actionData?.error) shopify.toast.show(actionData.error, { isError: true, duration: 5000 });
  }, [actionData, shopify]);

  const handleSave = useCallback(() => {
    submit({ intent: "updateWidgetConfig", primaryColor }, { method: "POST" });
  }, [submit, primaryColor]);

  const isSaving = navigation.state === "submitting";

  return (
    // No <Frame> wrapper needed — App Bridge v4 handles this
    <Page
      title="Settings"
      primaryAction={{ content: "Save", loading: isSaving, onAction: handleSave }}
    >
      <Layout>
        <Layout.AnnotatedSection
          title="Widget Appearance"
          description="Customize the visual style of your quiz widget."
        >
          <Card>
            <FormLayout>
              <TextField
                label="Primary color"
                value={primaryColor}
                onChange={setPrimaryColor}
                autoComplete="off"
                helpText="Hex color for buttons and accents (e.g. #5C6AC4)"
                prefix={<div style={{ width: 16, height: 16, borderRadius: 4, background: primaryColor }} />}
              />
            </FormLayout>
          </Card>
        </Layout.AnnotatedSection>

        <Layout.AnnotatedSection
          title="Current plan"
          description="Manage your subscription and billing."
        >
          <Card>
            <BlockStack gap="300">
              <InlineStack align="space-between" blockAlign="center">
                <BlockStack gap="100">
                  <Text variant="headingMd">{plan.charAt(0).toUpperCase() + plan.slice(1)} Plan</Text>
                  <Text tone="subdued" variant="bodySm">
                    {plan === "free" ? "1 quiz, 100 responses/month" : ""}
                  </Text>
                </BlockStack>
                <Button url="/app/billing" variant="plain">Manage billing</Button>
              </InlineStack>
              {plan === "free" && (
                <Banner tone="info" action={{ content: "Upgrade now", url: "/app/billing" }}>
                  <p>Upgrade to unlock unlimited quizzes and advanced features.</p>
                </Banner>
              )}
            </BlockStack>
          </Card>
        </Layout.AnnotatedSection>
      </Layout>
    </Page>
    // Toast handled via shopify.toast.show() above — no JSX needed
  );
}
```

