## ROUTE BOILERPLATE TEMPLATE

```tsx
// Minimal production-ready admin route template
import { json, type LoaderFunctionArgs, type ActionFunctionArgs } from "@shopify/shopify-app-react-router";
import { useLoaderData, useActionData, useNavigation } from "react-router";
import { authenticate } from "../shopify.server";
import db from "../db.server";
import { Page, Layout, Card, EmptyState, Toast, Frame } from "@shopify/polaris";
import { useState, useEffect } from "react";

export async function loader({ request }: LoaderFunctionArgs) {
  const { session } = await authenticate.admin(request);
  // ALL queries MUST include shop: session.shop
  const data = await db.quiz.findMany({ where: { shop: session.shop } });
  return json({ data });
}

export async function action({ request }: ActionFunctionArgs) {
  const { session } = await authenticate.admin(request);
  const formData = await request.formData();
  try {
    // Handle intents
    return json({ success: true, message: "Done" });
  } catch (error) {
    return json({ error: error instanceof Error ? error.message : "Error" }, { status: 500 });
  }
}

export default function MyPage() {
  const { data } = useLoaderData<typeof loader>();
  const actionData = useActionData<typeof action>();
  const navigation = useNavigation();
  const [toastActive, setToastActive] = useState(false);
  const [toastMessage, setToastMessage] = useState("");
  const [toastError, setToastError] = useState(false);

  useEffect(() => {
    if (actionData?.success) { setToastMessage(actionData.message); setToastError(false); setToastActive(true); }
    if (actionData?.error) { setToastMessage(actionData.error); setToastError(true); setToastActive(true); }
  }, [actionData]);

  if (data.length === 0) {
    return (
      <Page title="My Page">
        <EmptyState heading="Nothing here yet" image="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png">
          <p>Get started by creating your first item.</p>
        </EmptyState>
      </Page>
    );
  }

  return (
    <Frame>
      <Page title="My Page">
        <Layout><Layout.Section>
          <Card>
            {/* Content here */}
          </Card>
        </Layout.Section></Layout>
      </Page>
      {toastActive && <Toast content={toastMessage} error={toastError} onDismiss={() => setToastActive(false)} />}
    </Frame>
  );
}
```

---

## SELF-VALIDATION CHECKLIST

- [ ] `authenticate.admin(request)` first in every loader/action
- [ ] All queries include `shop: session.shop`
- [ ] Polaris v13 prop names used (tone, variant — not status, destructive)
- [ ] `Toast` inside `Frame` wrapper
- [ ] Empty state present when list is empty
- [ ] Loading state via `navigation.state !== "idle"`
- [ ] Error handling in every action with try/catch → json({ error })
- [ ] NavMenu updated when adding new top-level route
- [ ] `npm run typecheck` passes — no `any` types

---

## NEVER

- Never use raw HTML elements inside Polaris layouts (use Card, Layout.Section)
- Never use `router.push()` — use Polaris `url` prop or `redirect()`
- Never skip the empty state on list pages
- Never use deprecated Polaris v12 props (Stack, status on Badge)
- Never query DB without shop scoping
- Never forget Toast inside Frame

