    82→      case "deleteQuestion": {
    83→        const id = formData.get("id") as string;
    84→        await db.question.deleteMany({ where: { id, quizId } });
    85→        const remaining = await db.question.findMany({ where: { quizId }, orderBy: { position: "asc" } });
