## DRAG-AND-DROP REORDER (Optimistic UI)

```tsx
// Optimistic update: show new order immediately, persist to server
const [localOrder, setLocalOrder] = useState(questions.map(q => q.id));

function handleDragEnd(event: DragEndEvent) {
  const { active, over } = event;
  if (!over || active.id === over.id) return;
  const newOrder = arrayMove(localOrder, localOrder.indexOf(active.id as string), localOrder.indexOf(over.id as string));
  setLocalOrder(newOrder); // Immediate optimistic update
  submit({ intent: "reorderQuestions", orderedIds: JSON.stringify(newOrder) }, { method: "POST" });
}
