  const submit = useSubmit();

  return (
    <BlockStack gap="400">
      <FormLayout>
        <Checkbox
          label="Allow multiple selections"
          checked={settings.allowMultiple}
          onChange={(v) => onSettingsChange({ ...settings, allowMultiple: v })}
        />
        {settings.allowMultiple && (
          <TextField
            label="Maximum selections"
            type="number"
            value={String(settings.maxSelections || 2)}
            onChange={(v) => onSettingsChange({ ...settings, maxSelections: parseInt(v) })}
            autoComplete="off"
            min="2"
            max="10"
          />
        )}
        <Checkbox
          label="Randomize answer order"
          checked={settings.randomizeOrder}
          onChange={(v) => onSettingsChange({ ...settings, randomizeOrder: v })}
        />
      </FormLayout>

      {/* Answer list */}
      <BlockStack gap="200">
        <Text variant="headingSm" as="h3">Answer options</Text>
