          </InlineStack>
        )}
      </BlockStack>
    </BlockStack>
  );
}

// Individual answer row
function AnswerRow({ answer, index, canDelete, onChange }: AnswerRowProps) {
  const submit = useSubmit();
  const [productTags, setProductTags] = useState<string[]>(JSON.parse(answer.productTags || "[]"));
  const [tagInput, setTagInput] = useState("");

  const updateAnswer = (data: Partial<typeof answer>) => {
    submit({ intent: "updateAnswer", id: answer.id, ...data }, { method: "post" });
    onChange();
  };

  const handleAddTag = (tag: string) => {
    if (tag && !productTags.includes(tag)) {
      const newTags = [...productTags, tag];
      setProductTags(newTags);
      updateAnswer({ productTags: JSON.stringify(newTags) });
    }
    setTagInput("");
  };

  const handleRemoveTag = (tag: string) => {
    const newTags = productTags.filter(t => t !== tag);
    setProductTags(newTags);
    updateAnswer({ productTags: JSON.stringify(newTags) });
  };

  return (
    <Box
      background="bg-surface-secondary"
      borderWidth="025"
      borderColor="border"
      borderRadius="200"
      padding="300"
    >
      <BlockStack gap="200">
        <InlineStack gap="200" blockAlign="center">
