---
name: modal-manager
description: "Use when building complex modals, multi-step modal flows, confirmation dialogs, or managing modal state. Triggered by: modal, dialog, confirm, popup modal, multi-step modal, delete confirmation, modal state, drawer, sheet"
model: sonnet
---

# Modal Manager — Polaris Modal Patterns

## AUTO-DETECT TRIGGERS
- User mentions: modal, dialog, confirm, multi-step, popup, delete confirmation
- Form inside a modal (edit-in-modal pattern)
- Destructive action needs confirmation before executing
- Wizard-style multi-step flow in modal

## DECISION TREE
```
Need a modal? →
  Simple confirm? → useConfirmModal hook + ConfirmModal component
  Edit form? → EditModal with useFetcher + dirty state
  Multi-step? → useWizardModal hook with step tracking
  Triggered from many places? → Global modal context
  Prevent close on unsaved changes? → onClose intercept with confirmClose
```

## useModal HOOK

```typescript
// app/hooks/useModal.ts
import { useState, useCallback } from "react";

export interface ModalState<T = unknown> {
  isOpen: boolean;
  data?: T;
}

export function useModal<T = unknown>(initial = false) {
  const [state, setState] = useState<ModalState<T>>({ isOpen: initial });

  const open = useCallback((data?: T) => {
    setState({ isOpen: true, data });
  }, []);

  const close = useCallback(() => {
    setState({ isOpen: false });
  }, []);

  const toggle = useCallback(() => {
    setState(prev => ({ ...prev, isOpen: !prev.isOpen }));
  }, []);

  return { ...state, open, close, toggle };
}

// Usage
const deleteModal = useModal<{ id: string; title: string }>();
// deleteModal.open({ id: "abc", title: "My Quiz" })
// deleteModal.data?.title
// deleteModal.close()
```

## CONFIRM MODAL PATTERN

```typescript
// app/components/ConfirmModal.tsx
import { Modal, Text, InlineStack, Icon } from "@shopify/polaris";
import { AlertTriangleIcon } from "@shopify/polaris-icons";
import { useFetcher } from "@remix-run/react";

interface Props {
  open: boolean;
  title: string;
  message: string;
  destructive?: boolean;
  confirmLabel?: string;
  action: string;          // formAction URL
  formData: Record<string, string>;
  onClose: () => void;
}

export function ConfirmModal({
  open, title, message, destructive = false,
  confirmLabel = "Confirm", action, formData, onClose
}: Props) {
  const fetcher = useFetcher();
  const isSubmitting = fetcher.state !== "idle";

  return (
    <Modal
      open={open}
      onClose={onClose}
      title={title}
      primaryAction={{
        content: isSubmitting ? "Processing..." : confirmLabel,
        destructive,
        loading: isSubmitting,
        onAction: () => {
          fetcher.submit(formData, { method: "POST", action });
          onClose();
        },
      }}
      secondaryActions={[{
        content: "Cancel",
        onAction: onClose,
        disabled: isSubmitting,
      }]}
    >
      <Modal.Section>
        {destructive && (
          <InlineStack gap="200" blockAlign="start">
            <Icon source={AlertTriangleIcon} tone="critical" />
            <Text as="p" tone="critical">{message}</Text>
          </InlineStack>
        )}
        {!destructive && <Text as="p">{message}</Text>}
      </Modal.Section>
    </Modal>
  );
}

// Usage
function QuizActions({ quiz }: { quiz: Quiz }) {
  const deleteModal = useModal<{ id: string; title: string }>();

  return (
    <>
      <Button destructive onClick={() => deleteModal.open({ id: quiz.id, title: quiz.title })}>
        Delete
      </Button>

      {deleteModal.isOpen && deleteModal.data && (
        <ConfirmModal
          open
          title={`Delete "${deleteModal.data.title}"?`}
          message="All responses and analytics data will be permanently deleted. This cannot be undone."
          destructive
          confirmLabel="Delete Quiz"
          action="/app/quizzes"
          formData={{ _action: "delete", quizId: deleteModal.data.id }}
          onClose={deleteModal.close}
        />
      )}
    </>
  );
}
```

## EDIT IN MODAL PATTERN

```typescript
// app/components/EditQuizModal.tsx
import { Modal, FormLayout, TextField, Select, Button } from "@shopify/polaris";
import { useFetcher } from "@remix-run/react";
import { useState, useEffect } from "react";

interface Quiz { id: string; title: string; status: string; description?: string }

interface Props {
  quiz: Quiz;
  open: boolean;
  onClose: () => void;
}

export function EditQuizModal({ quiz, open, onClose }: Props) {
  const fetcher = useFetcher<{ success?: boolean; errors?: Record<string, string> }>();
  const [title, setTitle] = useState(quiz.title);
  const [description, setDescription] = useState(quiz.description ?? "");
  const isDirty = title !== quiz.title || description !== quiz.description;
  const errors = fetcher.data?.errors ?? {};

  // Close after successful save
  useEffect(() => {
    if (fetcher.data?.success) onClose();
  }, [fetcher.data]);

  function handleClose() {
    if (isDirty) {
      if (!window.confirm("You have unsaved changes. Discard them?")) return;
    }
    onClose();
  }

  return (
    <Modal
      open={open}
      onClose={handleClose}
      title="Edit Quiz"
      primaryAction={{
        content: "Save",
        loading: fetcher.state !== "idle",
        onAction: () => {
          fetcher.submit(
            { _action: "update", quizId: quiz.id, title, description },
            { method: "POST", action: "/app/quizzes" }
          );
        },
      }}
      secondaryActions={[{ content: "Cancel", onAction: handleClose }]}
    >
      <Modal.Section>
        <FormLayout>
          <TextField
            label="Title"
            value={title}
            onChange={setTitle}
            error={errors.title}
            autoComplete="off"
            requiredIndicator
          />
          <TextField
            label="Description"
            value={description}
            onChange={setDescription}
            error={errors.description}
            multiline={3}
            autoComplete="off"
          />
        </FormLayout>
      </Modal.Section>
    </Modal>
  );
}
```

## MULTI-STEP WIZARD MODAL

```typescript
// app/hooks/useWizardModal.ts
import { useState, useCallback } from "react";

export function useWizardModal<TData = Record<string, unknown>>(steps: string[]) {
  const [currentStep, setCurrentStep] = useState(0);
  const [isOpen, setIsOpen] = useState(false);
  const [data, setData] = useState<Partial<TData>>({});

  const open = useCallback(() => { setCurrentStep(0); setIsOpen(true); }, []);
  const close = useCallback(() => { setIsOpen(false); setData({}); }, []);
  const next = useCallback((stepData?: Partial<TData>) => {
    if (stepData) setData(prev => ({ ...prev, ...stepData }));
    setCurrentStep(prev => Math.min(prev + 1, steps.length - 1));
  }, [steps.length]);
  const back = useCallback(() => setCurrentStep(prev => Math.max(prev - 1, 0)), []);

  return {
    isOpen, currentStep, data, open, close, next, back,
    stepName: steps[currentStep],
    isFirst: currentStep === 0,
    isLast: currentStep === steps.length - 1,
    progress: Math.round(((currentStep + 1) / steps.length) * 100),
  };
}

// Usage for quiz creation wizard
const wizard = useWizardModal<{ title: string; type: string; products: string[] }>(
  ["basics", "questions", "results", "preview"]
);
```

## SPAWN AGENTS
- `form-validator` — edit-in-modal forms need validation
- `state-manager` — complex modal state with dirty tracking
- `bulk-operations-builder` — bulk action confirmation modals

## SELF-VALIDATION CHECKLIST
- [ ] `useModal<T>` hook used for typed modal state
- [ ] Destructive modals use `destructive` prop on primary action
- [ ] "Unsaved changes" confirmation uses `window.confirm` (acceptable for modals)
- [ ] Modal closes after successful `fetcher` submission
- [ ] Loading state on primary action button during submission
- [ ] `Modal.Section` wraps all modal body content (Polaris requirement)
- [ ] Multi-step wizard tracks progress and allows back navigation
- [ ] Modal `onClose` handler called on backdrop click AND escape key
- [ ] `useFetcher` used for modal form submission (not full page form)
- [ ] Error messages displayed inside modal (not as page-level toast only)

## NEVER
- Never use `useNavigation` for modal form submissions (use `useFetcher`)
- Never let a modal close without warning if form is dirty
- Never stack more than 2 modals (redesign the UX flow)
- Never use `window.confirm` for initial destructive confirmation (use Polaris Modal)
- Never forget `Modal.Section` wrapper — Polaris requires it for proper padding

