// app/routes/app.billing.tsx
import { json, type LoaderFunctionArgs, type ActionFunctionArgs } from "@shopify/shopify-app-react-router";
import { useLoaderData, useNavigation, useSubmit } from "react-router";
import { useAppBridge } from "@shopify/app-bridge-react";
import { useEffect, useState } from "react";
import { authenticate } from "~/shopify.server";
import { getSubscription, createSubscription, PLANS, type PlanId } from "~/services/billing.server";
import {
  Page, Layout, Card, BlockStack, InlineStack, Text, Badge,
  Button, Banner, Divider, List, Box, Icon, Grid, SkeletonPage, SkeletonBodyText
} from "@shopify/polaris";
import { CheckIcon } from "@shopify/polaris-icons";

export async function loader({ request }: LoaderFunctionArgs) {
  const { session } = await authenticate.admin(request);
  const subscription = await getSubscription(session.shop);
  return json({ subscription, shop: session.shop });
}

export async function action({ request }: ActionFunctionArgs) {
  const { session, admin } = await authenticate.admin(request);
  const formData = await request.formData();
  const intent = formData.get("intent") as string;

  try {
    if (intent === "upgrade") {
      const planId = formData.get("planId") as Exclude<PlanId, "free">;
      const confirmationUrl = await createSubscription(admin, session.shop, planId);
      return json({ redirect: confirmationUrl });
    }
    return json({ error: "Unknown action" }, { status: 400 });
  } catch (error) {
    return json({ error: error instanceof Error ? error.message : "Billing error" }, { status: 500 });
  }
}

export default function BillingPage() {
  const { subscription } = useLoaderData<typeof loader>();
  const navigation = useNavigation();
  const submit = useSubmit();
  const shopify = useAppBridge();
  const [billing, setBilling] = useState<"monthly" | "annual">("monthly");

  const actionData = useActionData<typeof action>();

  useEffect(() => {
    if (actionData?.redirect) {
      // Redirect to Shopify billing confirmation
      window.location.href = actionData.redirect;
    }
    if (actionData?.error) {
      shopify.toast.show(actionData.error, { isError: true });
    }
  }, [actionData, shopify]);

  const currentPlan = subscription.planId as PlanId;
  const planOrder: PlanId[] = ["free", "starter", "pro", "enterprise"];

  const getPrice = (plan: typeof PLANS.starter) => {
    if (!plan.price) return "Free";
    const price = billing === "annual" ? plan.price * 0.8 : plan.price;
    return `$${price.toFixed(2)}/mo`;
  };

  return (
    <Page
      title="Plans & Billing"
      backAction={{ content: "Settings", url: "/app/settings" }}
    >
      <BlockStack gap="600">
        {/* Current plan banner */}
        {subscription.trialDaysLeft > 0 && (
          <Banner tone="info" title={`${subscription.trialDaysLeft} days left in your free trial`}>
            <p>Your trial ends soon. Upgrade to keep access to all features.</p>
          </Banner>
        )}

        {/* Billing period toggle */}
        <Card>
          <InlineStack align="center" gap="400">
            <Text variant="bodyMd">Billed</Text>
            <InlineStack gap="300" blockAlign="center">
              <Button
                variant={billing === "monthly" ? "primary" : "plain"}
                onClick={() => setBilling("monthly")}
                size="slim"
              >
                Monthly
              </Button>
              <Button
                variant={billing === "annual" ? "primary" : "plain"}
                onClick={() => setBilling("annual")}
                size="slim"
              >
                Annual <Badge tone="success">Save 20%</Badge>
              </Button>
            </InlineStack>
          </InlineStack>
        </Card>

        {/* Plan comparison grid */}
        <Grid>
          {(Object.entries(PLANS) as [PlanId, typeof PLANS.free][]).map(([planId, plan]) => {
            const isCurrent = planId === currentPlan;
            const isUpgrade = planOrder.indexOf(planId) > planOrder.indexOf(currentPlan);
            const isDowngrade = planOrder.indexOf(planId) < planOrder.indexOf(currentPlan);
            const isSubmitting = navigation.state === "submitting" && navigation.formData?.get("planId") === planId;

            return (
              <Grid.Cell key={planId} columnSpan={{ xs: 6, sm: 6, md: 3, lg: 3 }}>
                <Card background={planId === "pro" ? "bg-surface-success" : undefined}>
                  <BlockStack gap="400">
                    {/* Plan header */}
                    <BlockStack gap="200">
                      <InlineStack align="space-between" blockAlign="center">
                        <Text variant="headingLg" as="h2">{plan.name}</Text>
                        {isCurrent && <Badge tone="success">Current plan</Badge>}
                        {planId === "pro" && !isCurrent && <Badge tone="info">Popular</Badge>}
                      </InlineStack>
                      <Text variant="heading2xl" fontWeight="bold">
                        {getPrice(plan as typeof PLANS.starter)}
                      </Text>
                      {billing === "annual" && plan.price > 0 && (
                        <Text tone="subdued" variant="bodySm">
                          ${(plan.price * 0.8 * 12).toFixed(0)}/year (save ${(plan.price * 12 * 0.2).toFixed(0)})
                        </Text>
                      )}
                    </BlockStack>

                    <Divider />

                    {/* Features */}
                    <List type="bullet">
                      {plan.features.map((feature, i) => (
                        <List.Item key={i}>
                          <InlineStack gap="200" blockAlign="center">
                            <Icon source={CheckIcon} tone="success" />
                            <Text>{feature}</Text>
                          </InlineStack>
                        </List.Item>
                      ))}
                    </List>

                    {/* CTA */}
                    <Box paddingBlockStart="200">
                      {isCurrent ? (
                        <Button disabled fullWidth>Current plan</Button>
                      ) : isUpgrade && planId !== "free" ? (
                        <Button
                          variant="primary"
                          fullWidth
                          loading={isSubmitting}
                          onClick={() => submit({ intent: "upgrade", planId }, { method: "post" })}
                        >
                          Upgrade to {plan.name}
                        </Button>
                      ) : isDowngrade && planId === "free" ? (
                        <Button variant="plain" fullWidth url="https://help.shopify.com">
                          Downgrade to Free
                        </Button>
                      ) : (
                        <Button
                          fullWidth
                          loading={isSubmitting}
                          onClick={() => submit({ intent: "upgrade", planId }, { method: "post" })}
                        >
                          Switch to {plan.name}
                        </Button>
                      )}
                    </Box>
                  </BlockStack>
                </Card>
              </Grid.Cell>
            );
          })}
        </Grid>

        {/* Current usage */}
        <Layout>
          <Layout.Section>
            <Card>
              <BlockStack gap="400">
                <Text variant="headingMd" as="h2">Current usage</Text>
                <Grid>
                  <Grid.Cell columnSpan={{ xs: 6, sm: 3, md: 3, lg: 3 }}>
                    <BlockStack gap="100">
                      <Text tone="subdued" variant="bodySm">Quizzes</Text>
                      <Text variant="headingLg">{subscription.quizLimit === Infinity ? "Unlimited" : `${subscription.quizLimit} max`}</Text>
                    </BlockStack>
                  </Grid.Cell>
                  <Grid.Cell columnSpan={{ xs: 6, sm: 3, md: 3, lg: 3 }}>
                    <BlockStack gap="100">
                      <Text tone="subdued" variant="bodySm">Responses / month</Text>
                      <Text variant="headingLg">{subscription.responseLimit === Infinity ? "Unlimited" : subscription.responseLimit.toLocaleString()}</Text>
                    </BlockStack>
                  </Grid.Cell>
                </Grid>
              </BlockStack>
            </Card>
          </Layout.Section>
        </Layout>
      </BlockStack>
    </Page>
  );
}
```

