                <Card background={planId === "pro" ? "bg-surface-success" : undefined}>
                  <BlockStack gap="400">
                    {/* Plan header */}
                    <BlockStack gap="200">
                      <InlineStack align="space-between" blockAlign="center">
                        <Text variant="headingLg" as="h2">{plan.name}</Text>
                        {isCurrent && <Badge tone="success">Current plan</Badge>}
                        {planId === "pro" && !isCurrent && <Badge tone="info">Popular</Badge>}
                      </InlineStack>
                      <Text variant="heading2xl" fontWeight="bold">
                        {getPrice(plan as typeof PLANS.starter)}
                      </Text>
                      {billing === "annual" && plan.price > 0 && (
                        <Text tone="subdued" variant="bodySm">
                          ${(plan.price * 0.8 * 12).toFixed(0)}/year (save ${(plan.price * 12 * 0.2).toFixed(0)})
                        </Text>
                      )}
                    </BlockStack>

                    <Divider />

                    {/* Features */}
                    <List type="bullet">
                      {plan.features.map((feature, i) => (
                        <List.Item key={i}>
                          <InlineStack gap="200" blockAlign="center">
                            <Icon source={CheckIcon} tone="success" />
                            <Text>{feature}</Text>
                          </InlineStack>
                        </List.Item>
                      ))}
                    </List>

                    {/* CTA */}
                    <Box paddingBlockStart="200">
                      {isCurrent ? (
                        <Button disabled fullWidth>Current plan</Button>
                      ) : isUpgrade && planId !== "free" ? (
                        <Button
                          variant="primary"
                          fullWidth
                          loading={isSubmitting}
                          onClick={() => submit({ intent: "upgrade", planId }, { method: "post" })}
                        >
                          Upgrade to {plan.name}
                        </Button>
                      ) : isDowngrade && planId === "free" ? (
                        <Button variant="plain" fullWidth url="https://help.shopify.com">
                          Downgrade to Free
                        </Button>
                      ) : (
                        <Button
                          fullWidth
                          loading={isSubmitting}
                          onClick={() => submit({ intent: "upgrade", planId }, { method: "post" })}
                        >
                          Switch to {plan.name}
                        </Button>
                      )}
                    </Box>
                  </BlockStack>
                </Card>
              </Grid.Cell>
            );
          })}
        </Grid>

        {/* Current usage */}
        <Layout>
          <Layout.Section>
            <Card>
              <BlockStack gap="400">
                <Text variant="headingMd" as="h2">Current usage</Text>
                <Grid>
                  <Grid.Cell columnSpan={{ xs: 6, sm: 3, md: 3, lg: 3 }}>
                    <BlockStack gap="100">
                      <Text tone="subdued" variant="bodySm">Quizzes</Text>
                      <Text variant="headingLg">{subscription.quizLimit === Infinity ? "Unlimited" : `${subscription.quizLimit} max`}</Text>
                    </BlockStack>
                  </Grid.Cell>
                  <Grid.Cell columnSpan={{ xs: 6, sm: 3, md: 3, lg: 3 }}>
                    <BlockStack gap="100">
                      <Text tone="subdued" variant="bodySm">Responses / month</Text>
                      <Text variant="headingLg">{subscription.responseLimit === Infinity ? "Unlimited" : subscription.responseLimit.toLocaleString()}</Text>
                    </BlockStack>
                  </Grid.Cell>
                </Grid>
              </BlockStack>
            </Card>
          </Layout.Section>
        </Layout>
      </BlockStack>
    </Page>
  );
}
