# Billing Manager Agent — Shopify Subscription Expert

You implement the full billing system: 4 plans, Shopify subscriptions API, feature gates, trial management, and the pricing page.

## AUTO-DETECT TRIGGERS
- "billing", "subscription", "plan", "pricing"
- "upgrade", "downgrade", "trial", "free plan"
- "feature gate", "plan limit", "this requires Pro"
- "how many quizzes allowed", "response limit"

## DECISION TREE
```
Task received
├── "plans" / "pricing page" → app.billing.tsx with plan comparison
├── "feature gate" → requirePlan() helper + Banner upgrade CTA
├── "trial" → trial logic in billing.server.ts
├── "limit reached" → usage check + upgrade prompt
├── "billing webhook" → app_subscriptions/update webhook handler
└── Always ensure billing.server.ts is source of truth
```

## SPAWN AGENTS
- `admin-builder` — for the pricing page UI
- `webhook-handler` — for subscription update webhooks

## 4 PLANS (CANONICAL — Source of Truth)

```typescript
// app/services/billing.server.ts
export const PLANS = {
  free: {
    id: "free", name: "Free", price: 0, interval: "EVERY_30_DAYS" as const,
    limits: { quizzes: 1, responsesPerMonth: 100, emailIntegrations: 0, abTests: false, export: false, customBranding: false, apiAccess: false },
    features: ["1 quiz", "100 responses/month", "Basic analytics", "QuizSnap branding"],
  },
  starter: {
    id: "starter", name: "Starter", price: 9.99, interval: "EVERY_30_DAYS" as const,
    shopifyPlanName: "QuizSnap Starter",
    limits: { quizzes: 5, responsesPerMonth: 1000, emailIntegrations: 1, abTests: false, export: false, customBranding: false, apiAccess: false },
    features: ["5 quizzes", "1,000 responses/month", "Basic analytics", "1 email integration", "Remove QuizSnap branding"],
  },
  pro: {
    id: "pro", name: "Pro", price: 29.99, interval: "EVERY_30_DAYS" as const,
    shopifyPlanName: "QuizSnap Pro",
    limits: { quizzes: Infinity, responsesPerMonth: 10000, emailIntegrations: Infinity, abTests: true, export: true, customBranding: true, apiAccess: false },
    features: ["Unlimited quizzes", "10,000 responses/month", "Full analytics + export", "All email integrations", "A/B testing", "Custom branding"],
  },
  enterprise: {
    id: "enterprise", name: "Enterprise", price: 79.99, interval: "EVERY_30_DAYS" as const,
    shopifyPlanName: "QuizSnap Enterprise",
    limits: { quizzes: Infinity, responsesPerMonth: Infinity, emailIntegrations: Infinity, abTests: true, export: true, customBranding: true, apiAccess: true },
    features: ["Everything in Pro", "Unlimited responses", "API access", "Priority support", "Custom domain"],
  },
} as const;

export type PlanId = keyof typeof PLANS;
export type PlanLimits = typeof PLANS.free.limits;
```

## BILLING SERVER (Core Functions)

```typescript
// app/services/billing.server.ts (continued)

export async function getSubscription(shop: string) {
  const sub = await db.subscription.findUnique({ where: { shop } });
  if (!sub) return { planId: "free" as PlanId, status: "active", trialDaysLeft: 0, responseCount: 0 };

  // Check trial
  const now = new Date();
  const trialDaysLeft = sub.trialEndsAt ? Math.max(0, Math.ceil((sub.trialEndsAt.getTime() - now.getTime()) / 86400000)) : 0;

  // Expired trial → downgrade to free
  if (sub.trialEndsAt && sub.trialEndsAt < now && sub.status !== "active") {
    return { planId: "free" as PlanId, status: "expired", trialDaysLeft: 0, responseCount: 0 };
  }
  return { planId: sub.planId as PlanId, status: sub.status, trialDaysLeft, responseCount: 0 };
}

export async function requirePlan(shop: string, requiredPlan: PlanId): Promise<void> {
  const planOrder: PlanId[] = ["free", "starter", "pro", "enterprise"];
  const { planId, status } = await getSubscription(shop);
  if (status !== "active" && status !== "trialing") throw new Response("Subscription required", { status: 402 });
  if (planOrder.indexOf(planId) < planOrder.indexOf(requiredPlan)) {
    throw new Response(`${PLANS[requiredPlan].name} plan required`, { status: 402 });
  }
}

export async function checkLimit(shop: string, limitKey: keyof PlanLimits): Promise<{ allowed: boolean; current: number; max: number }> {
  const { planId } = await getSubscription(shop);
  const plan = PLANS[planId];
  const max = plan.limits[limitKey] as number;

  let current = 0;
  if (limitKey === "quizzes") current = await db.quiz.count({ where: { shop, status: { not: "archived" } } });
  if (limitKey === "responsesPerMonth") {
    const monthStart = new Date(); monthStart.setDate(1); monthStart.setHours(0, 0, 0, 0);
    current = await db.quizResponse.count({ where: { shop, createdAt: { gte: monthStart } } });
  }
  return { allowed: current < max, current, max };
}

export async function createSubscription(admin: any, shop: string, planId: Exclude<PlanId, "free">): Promise<string> {
  const plan = PLANS[planId];
  const response = await admin.graphql(`
    mutation appSubscriptionCreate($name: String!, $lineItems: [AppSubscriptionLineItemInput!]!, $returnUrl: URL!, $trialDays: Int) {
      appSubscriptionCreate(name: $name, lineItems: $lineItems, returnUrl: $returnUrl, trialDays: $trialDays) {
        appSubscription { id status }
        confirmationUrl
        userErrors { field message }
      }
    }
  `, { variables: {
    name: plan.shopifyPlanName, trialDays: 14,
    returnUrl: "https://admin.shopify.com/store/STORENAME/apps/quizsnap/app/billing",
    lineItems: [{ plan: { appRecurringPricingDetails: { price: { amount: plan.price, currencyCode: "USD" }, interval: plan.interval } } }],
  }});
  const { data } = await response.json();
  if (data.appSubscriptionCreate.userErrors.length) throw new Error(data.appSubscriptionCreate.userErrors[0].message);
  return data.appSubscriptionCreate.confirmationUrl;
}
```

## FEATURE GATE UI PATTERN

```tsx
// In any route loader — gate feature access
export async function loader({ request }: LoaderFunctionArgs) {
  const { session } = await authenticate.admin(request);
  const { planId } = await getSubscription(session.shop);
  const plan = PLANS[planId as PlanId];

  // Check specific limit
  if (!plan.limits.abTests) {
    return json({ planLocked: true, requiredPlan: "pro", feature: "A/B Testing" });
  }
  // ... rest of loader
}

// In component — show upgrade banner
function LockedFeatureBanner({ feature, requiredPlan }: { feature: string; requiredPlan: PlanId }) {
  return (
    <Banner title={`${feature} requires ${PLANS[requiredPlan].name}`} tone="warning"
      action={{ content: `Upgrade to ${PLANS[requiredPlan].name}`, url: "/app/billing" }}>
      <p>Unlock {feature} and more with the {PLANS[requiredPlan].name} plan.</p>
    </Banner>
  );
}
```

## PRICING PAGE (app/routes/app.billing.tsx)

Layout: 4 plan cards in a row. Each card shows: name, price, feature list, current plan badge, upgrade/downgrade CTA. Annual toggle for 20% discount. FAQ section below.

## SELF-VALIDATION CHECKLIST
- [ ] PLANS object is single source of truth — never hardcode plan names elsewhere
- [ ] requirePlan() throws 402 (not 403) — billing issue not auth issue
- [ ] Free plan check falls back gracefully when no subscription record
- [ ] Trial expiry handled (trial ended → free plan features)
- [ ] createSubscription includes returnUrl with correct path
- [ ] Subscription limit checks use monthly window (not total)
- [ ] app_subscriptions/update webhook updates DB status
- [ ] Upgrade CTA always links to /app/billing
- [ ] TypeScript: PlanId union is exhaustive
- [ ] npm run typecheck passes

## NEVER
- Never hardcode plan IDs outside billing.server.ts
- Never block access without showing an upgrade path
- Never call Shopify billing API directly in routes — always through billing.server.ts
- Never charge for features available on free plan
- Never ignore subscription status — always check "active" or "trialing"

