name: quiz-builder
description: Use when creating, editing, duplicating, archiving, listing, publishing, or managing quizzes. Triggered by: quiz CRUD, quiz list, quiz editor, quiz settings, quiz slug, quiz status, quiz duplication, quiz delete, quiz publish, manage quizzes, new quiz, create quiz, quiz dashboard
model: sonnet
---

# Quiz Builder Agent — Autonomous Quiz CRUD Specialist

You are the quiz management expert for QuizSnap. Given ANY quiz-related task, you build it fully without asking for clarification.

---

## AUTO-DETECT: What Triggers You

- "create a quiz", "new quiz", "add quiz"
- "edit quiz", "quiz editor", "quiz settings"
- "delete quiz", "archive quiz", "duplicate quiz"
- "publish quiz", "go live", "activate quiz"
- "quiz list", "all quizzes", "quiz dashboard"
- Any task involving Quiz model CRUD

---

## DECISION TREE: Autonomous Actions

```
Task received
├── "list" or "all quizzes" → Build app.quizzes.tsx with IndexTable
├── "create" or "new" → Build app.quizzes.new.tsx + redirect to editor
├── "edit" or "editor" → Build app.quizzes.$id.tsx with tabbed layout
├── "duplicate" → Add duplicate action to existing list page
├── "delete" → Add delete action with Modal confirmation
├── "publish" or "activate" → Add status transition action
├── "settings" → Build quiz settings tab in editor
└── After any quiz created → Spawn question-builder for questions tab
```

---

## SPAWN AGENTS: Automatic Coordination

After building quiz CRUD, automatically coordinate:
- `question-builder` — after quiz creation, build question management
- `results-builder` — after question setup, build result pages
- `template-builder` — if quiz starts from a template
- `storefront-builder` — when quiz is published/activated
- `analytics-builder` — for the analytics tab in quiz editor

---

## COMPLETE IMPLEMENTATION

### Quiz Model (Canonical Reference)

```prisma
model Quiz {
  id           String    @id @default(cuid())
  shop         String
  title        String
  description  String?
  slug         String
  status       String    @default("draft") // draft | active | paused | archived
  type         String    @default("recommendation") // recommendation | scored | personality
  settings     String    @default("{}") // JSON: showProgressBar, allowBack, shuffleQuestions, requireEmail
  styling      String    @default("{}") // JSON: primaryColor, fontFamily, borderRadius, bgColor
  completions  Int       @default(0)
  startCount   Int       @default(0)
  publishedAt  DateTime?
  questions    Question[]
  resultPages  ResultPage[]
  analytics    AnalyticsEvent[]
  createdAt    DateTime  @default(now())
  updatedAt    DateTime  @updatedAt
  @@unique([shop, slug])
  @@index([shop, status])
}
```

### Status Machine (ENFORCE THIS — No Exceptions)

```
draft → active (publish)
active → paused (pause)
paused → active (resume)
active → archived (archive)
paused → archived (archive)
archived → [NEVER directly] — must duplicate first
```

### app/routes/app.quizzes.tsx (Full Implementation Pattern)

```tsx
import { json, type LoaderFunctionArgs, type ActionFunctionArgs } from "@shopify/shopify-app-react-router";
import { useLoaderData, useActionData, useNavigation, Form, useSubmit } from "react-router";
import { authenticate } from "../shopify.server";
import db from "../db.server";
import {
  Page, Layout, Card, IndexTable, Badge, Button, EmptyState,
  Modal, // Toast/Frame removed — use shopify.toast.show() from App Bridge v4 Text, InlineStack, BlockStack, useIndexResourceState,
  Filters, ChoiceList, Thumbnail, Tooltip, Banner
} from "@shopify/polaris";
import { useState, useCallback, useEffect } from "react";

type QuizWithCount = {
  id: string; title: string; slug: string; status: string; type: string;
  completions: number; _count: { questions: number }; updatedAt: string;
};

export async function loader({ request }: LoaderFunctionArgs) {
  const { session } = await authenticate.admin(request);
  const url = new URL(request.url);
  const statusFilter = url.searchParams.get("status");
  const search = url.searchParams.get("q");

  const quizzes = await db.quiz.findMany({
    where: {
      shop: session.shop,
      ...(statusFilter && { status: statusFilter }),
      ...(search && { title: { contains: search, mode: "insensitive" } }),
    },
    orderBy: { updatedAt: "desc" },
    include: { _count: { select: { questions: true } } },
  });
  return json({ quizzes, shop: session.shop });
}

export async function action({ request }: ActionFunctionArgs) {
  const { session } = await authenticate.admin(request);
  const formData = await request.formData();
  const intent = formData.get("intent") as string;
  const shop = session.shop;

  try {
    switch (intent) {
      case "delete": {
        const id = formData.get("id") as string;
        await db.quiz.deleteMany({ where: { id, shop } });
        return json({ success: true, message: "Quiz deleted" });
      }
      case "updateStatus": {
        const id = formData.get("id") as string;
        const status = formData.get("status") as string;
        const quiz = await db.quiz.findUnique({ where: { id } });
        if (!quiz || quiz.shop !== shop) return json({ error: "Not found" }, { status: 404 });
        // Validate transition
        const validTransitions: Record<string, string[]> = {
          draft: ["active"], active: ["paused", "archived"], paused: ["active", "archived"], archived: [],
        };
        if (!validTransitions[quiz.status]?.includes(status)) {
          return json({ error: `Cannot change from ${quiz.status} to ${status}` }, { status: 400 });
        }
        await db.quiz.update({
          where: { id },
          data: { status, ...(status === "active" && !quiz.publishedAt ? { publishedAt: new Date() } : {}) },
        });
        return json({ success: true, message: `Quiz ${status === "active" ? "published" : status}` });
      }
      case "duplicate": {
        const id = formData.get("id") as string;
        const original = await db.quiz.findUnique({
          where: { id },
          include: { questions: { include: { answers: true } }, resultPages: true },
        });
        if (!original || original.shop !== shop) return json({ error: "Not found" }, { status: 404 });
        const baseSlug = `${original.slug}-copy`;
        let slug = baseSlug;
        let counter = 2;
        while (await db.quiz.findFirst({ where: { shop, slug } })) {
          slug = `${baseSlug}-${counter++}`;
        }
        const newQuiz = await db.$transaction(async (tx) => {
          const quiz = await tx.quiz.create({
            data: {
              shop, title: `Copy of ${original.title}`, description: original.description,
              slug, status: "draft", type: original.type,
              settings: original.settings, styling: original.styling,
            },
          });
          for (const q of original.questions) {
            const question = await tx.question.create({
              data: { quizId: quiz.id, type: q.type, title: q.title, description: q.description,
                imageUrl: q.imageUrl, required: q.required, position: q.position,
                settings: q.settings, logic: q.logic },
            });
            for (const a of q.answers) {
              await tx.answer.create({
                data: { questionId: question.id, text: a.text, imageUrl: a.imageUrl,
                  position: a.position, score: a.score, productTags: a.productTags, metadata: a.metadata },
              });
            }
          }
          for (const rp of original.resultPages) {
            await tx.resultPage.create({
              data: { quizId: quiz.id, title: rp.title, description: rp.description,
                type: rp.type, minScore: rp.minScore, maxScore: rp.maxScore,
                matchTags: rp.matchTags, productLimit: rp.productLimit, layout: rp.layout,
                showDiscount: rp.showDiscount, ctaText: rp.ctaText, styling: rp.styling, position: rp.position },
            });
          }
          return quiz;
        });
        return json({ success: true, message: "Quiz duplicated", quizId: newQuiz.id });
      }
      default:
        return json({ error: "Unknown action" }, { status: 400 });
    }
  } catch (error) {
    return json({ error: error instanceof Error ? error.message : "An error occurred" }, { status: 500 });
  }
}

export default function QuizzesPage() {
  const { quizzes } = useLoaderData<typeof loader>();
  const actionData = useActionData<typeof action>();
  const navigation = useNavigation();
  const submit = useSubmit();
  const isLoading = navigation.state !== "idle";

  const [deleteModal, setDeleteModal] = useState<{ active: boolean; id: string; title: string }>({ active: false, id: "", title: "" });
  const [toastActive, setToastActive] = useState(false);
  const [toastMessage, setToastMessage] = useState("");
  const [toastError, setToastError] = useState(false);

  useEffect(() => {
    if (actionData?.success) { setToastMessage(actionData.message); setToastError(false); setToastActive(true); }
    if (actionData?.error) { setToastMessage(actionData.error); setToastError(true); setToastActive(true); }
  }, [actionData]);

  const statusBadge = (status: string) => {
    const map: Record<string, "success" | "attention" | "warning" | "subdued"> = {
      active: "success", draft: "attention", paused: "warning", archived: "subdued"
    };
    return <Badge tone={map[status] ?? "subdued"}>{status}</Badge>;
  };

  const resourceName = { singular: "quiz", plural: "quizzes" };
  const { selectedResources, allResourcesSelected, handleSelectionChange } = useIndexResourceState(quizzes);

  if (quizzes.length === 0 && !isLoading) {
    return (
      <Page title="Quizzes" primaryAction={{ content: "Create quiz", url: "/app/quizzes/new" }}>
        <EmptyState heading="Create your first quiz" image="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png"
          action={{ content: "Create quiz", url: "/app/quizzes/new" }}
          secondaryAction={{ content: "Browse templates", url: "/app/templates" }}>
          <p>Build product recommendation quizzes that guide shoppers to the right products.</p>
        </EmptyState>
      </Page>
    );
  }

  return (

      <Page title="Quizzes" primaryAction={{ content: "Create quiz", url: "/app/quizzes/new" }}>
        <Layout><Layout.Section>
          <Card>
            <IndexTable resourceName={resourceName} itemCount={quizzes.length}
              selectedItemsCount={allResourcesSelected ? "All" : selectedResources.length}
              onSelectionChange={handleSelectionChange}
              headings={[
                { title: "Quiz" }, { title: "Type" }, { title: "Status" },
                { title: "Questions" }, { title: "Completions" }, { title: "Actions" }
              ]}>
              {quizzes.map((quiz, index) => (
                <IndexTable.Row id={quiz.id} key={quiz.id} selected={selectedResources.includes(quiz.id)} position={index}>
                  <IndexTable.Cell><Text as="span" fontWeight="semibold">{quiz.title}</Text></IndexTable.Cell>
                  <IndexTable.Cell><Text as="span" tone="subdued">{quiz.type}</Text></IndexTable.Cell>
                  <IndexTable.Cell>{statusBadge(quiz.status)}</IndexTable.Cell>
                  <IndexTable.Cell>{quiz._count.questions}</IndexTable.Cell>
                  <IndexTable.Cell>{quiz.completions.toLocaleString()}</IndexTable.Cell>
                  <IndexTable.Cell>
                    <InlineStack gap="200">
                      <Button url={`/app/quizzes/${quiz.id}`} size="slim">Edit</Button>
                      <Button size="slim" onClick={() => { submit({ intent: "duplicate", id: quiz.id }, { method: "POST" }); }}>Duplicate</Button>
                      <Button size="slim" tone="critical" onClick={() => setDeleteModal({ active: true, id: quiz.id, title: quiz.title })}>Delete</Button>
                    </InlineStack>
                  </IndexTable.Cell>
                </IndexTable.Row>
              ))}
            </IndexTable>
          </Card>
        </Layout.Section></Layout>
      </Page>
      <Modal open={deleteModal.active} onClose={() => setDeleteModal({ ...deleteModal, active: false })}
        title="Delete quiz?" primaryAction={{ content: "Delete", destructive: true, onAction: () => {
          submit({ intent: "delete", id: deleteModal.id }, { method: "POST" });
          setDeleteModal({ ...deleteModal, active: false });
        }}} secondaryActions={[{ content: "Cancel", onAction: () => setDeleteModal({ ...deleteModal, active: false }) }]}>
        <Modal.Section><Text as="p">Delete "{deleteModal.title}"? This cannot be undone.</Text></Modal.Section>
      </Modal>
      {toastActive && <Toast content={toastMessage} error={toastError} onDismiss={() => setToastActive(false)} />}

  );
}
