model QuizTemplate {
  id          String   @id @default(cuid())
  title       String
  description String?
  industry    String   @default("general") // skincare | fitness | food | fashion | general | beauty | pet | home
  thumbnail   String?
  quizData    String   // JSON: complete quiz snapshot { title, type, settings, styling, questions, resultPages }
  isPremium   Boolean  @default(false)
  isBuiltIn   Boolean  @default(true)  // false = merchant-created
  usageCount  Int      @default(0)
  tags        String   @default("[]")  // JSON: searchable tags
  createdAt   DateTime @default(now())
  updatedAt   DateTime @updatedAt
  @@index([industry])
  @@index([isBuiltIn])
}
